var t=`0812-chambo-with-ndiwo`;var n=`world-0812`;var a=`MW`;var s=`eastern-africa`;var o=4;var r=59;var l={en:`Chambo with Ndiwo`,ua:`Чамбо з ндіво`};var d={en:`Chambo with Ndiwo is a Malawi dish made with tilapia, lemon juice, yellow onion, tomato. This home-scale recipe assigns measured ingredients to the steps where they are used. Tilapia stands in for Malawi chambo, a different fish species.`,ua:`Чамбо з ндіво, страва кухні країни Малаві. Основні складники: тилапія, лимонний сік, жовта цибуля, помідор. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Тіляпія замінює малавійського чамбо, це інший вид риби.`};var m=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 20 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 20 хвилин.`,t:[`marinating`],m:20,i:[[`tilapia`,750,`g`],[`lemon-juice`,35,`ml`],[`ground-coriander`,3,`g`],[`table-salt`,null,`to_taste`]]},{en:`Grill over medium-high heat for about 17 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 17 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:17,i:[[`canola-oil`,35,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,140,`g`],[`tomato`,230,`g`],[`spinach`,260,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 10 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 10 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:10,i:[[`peanut-butter`,75,`g`],[`water`,230,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`lemon`,1,`pcs`]]}];var g={slug:t,id:n,country:`MW`,region:s,servings:4,minutes:59,title:l,text:d,steps:m};export{a as country,g as default,n as id,r as minutes,s as region,o as servings,t as slug,m as steps,d as text,l as title};